#!/usr/bin/env bash
# ===========================================
# check.sh — Verify symlinks, generated files, and repo status
# ===========================================
# Checks that the enabled modules are linked into the repo, generated files
# exist, and reports (never commits) uncommitted changes in the repo.

set -euo pipefail

DOTFILES_DIR="$(cd "$(dirname "$0")" && pwd)"

# ------------------------------------
# Load config and secrets (modules, Claude accounts)
# ------------------------------------

# shellcheck source=lib/dotfiles.sh
source "$DOTFILES_DIR/lib/dotfiles.sh"
load_config

# ------------------------------------
# Helpers
# ------------------------------------

info()    { printf "\033[1;34m%s\033[0m\n" "$1"; }
success() { printf "\033[1;32m%s\033[0m\n" "$1"; }
warn()    { printf "\033[1;33m%s\033[0m\n" "$1"; }

check_symlink() {
  local system_path="$1" expected_target="$2"

  if [ ! -e "$system_path" ]; then
    warn "MISSING: $system_path"
    return
  fi

  if [ -L "$system_path" ]; then
    local actual_target
    actual_target="$(readlink "$system_path")"
    if [ "$actual_target" = "$expected_target" ]; then
      success "OK: $system_path → repo"
    else
      warn "WRONG LINK: $system_path → $actual_target (expected $expected_target)"
    fi
  else
    warn "NOT LINKED: $system_path (run install.sh to link)"
  fi
}

# check_module_link <module> <path> <target> — only for enabled modules
check_module_link() {
  module_enabled "$1" && check_symlink "$2" "$3"
  return 0
}

# check_link_or_merge <module> <path> <target> <local-file> — linked, or generated
# from the tracked config + local additions when the local file exists
check_link_or_merge() {
  module_enabled "$1" || return 0
  if [ -f "$4" ]; then
    if [ -f "$2" ] && [ ! -L "$2" ] && grep -q "^# Auto-generated by install.sh" "$2"; then
      success "OK: $2 (generated with ${4##*/})"
    else
      warn "STALE: $2 (${4##*/} exists, run install.sh)"
    fi
  else
    check_symlink "$2" "$3"
  fi
}

check_dir() {
  local dir="$1" label="$2"
  if [ -d "$dir" ]; then
    success "OK: $label"
  else
    warn "MISSING: $label (run install.sh)"
  fi
}

# ------------------------------------
# Config files
# ------------------------------------

echo ""
info "=== Config ($DOTFILES_CONFIG_HOME) ==="
echo ""

[ -f "$CONFIG_FILE" ] && success "OK: config.sh" || warn "MISSING: config.sh (run install.sh to create it)"
if [ -f "$SECRETS_FILE" ]; then
  # GNU stat first: on Linux "stat -f" means filesystem info and still succeeds
  perms="$(stat -c %a "$SECRETS_FILE" 2>/dev/null || stat -f %Lp "$SECRETS_FILE")"
  if [ "$perms" = 600 ]; then
    success "OK: .secrets (600)"
  else
    warn "INSECURE: .secrets is $perms (run: chmod 600 $SECRETS_FILE)"
  fi
fi
info "Modules: ${DOTFILES_MODULES:-(none)}"
while IFS='|' read -r required needed_by reason; do
  [ -n "$required" ] && warn "REQUIRES: $needed_by needs module '$required' — $reason"
done <<< "$(missing_requirements)"

# ------------------------------------
# Check symlink health
# ------------------------------------

echo ""
info "=== Checking symlink status ==="
echo ""

check_module_link zsh      "$HOME/.zshrc"                   "$DOTFILES_DIR/shell/.zshrc"
check_module_link git      "$HOME/.config/git/ignore"       "$DOTFILES_DIR/git/.gitignore"
check_module_link tmux     "$HOME/.tmux.conf"               "$DOTFILES_DIR/tmux/.tmux.conf"
check_module_link ghostty  "$HOME/.config/ghostty/config"   "$DOTFILES_DIR/terminal/ghostty/config"
check_module_link nvim     "$HOME/.config/nvim"             "$DOTFILES_DIR/editor/nvim"
check_link_or_merge starship "$HOME/.config/starship.toml" "$DOTFILES_DIR/prompt/starship.toml" \
  "$DOTFILES_CONFIG_HOME/starship.local.toml"
check_module_link sesh     "$HOME/.config/sesh/sesh.toml"   "$DOTFILES_DIR/tools/sesh.toml"
check_module_link vpn      "$HOME/bin/vpn"                  "$DOTFILES_DIR/tools/vpn"

if module_enabled keyboard-ua-ru; then
  check_module_link tmux    "$HOME/.config/tmux/keyboard-ua-ru.conf" "$DOTFILES_DIR/tmux/keyboard-ua-ru.conf"
  check_module_link ghostty "$HOME/.config/ghostty/keyboard-ua-ru"   "$DOTFILES_DIR/terminal/ghostty/keyboard-ua-ru"
fi

if module_enabled tmux && [ "${TMUX_NESTED_TOGGLE:-true}" != false ]; then
  check_symlink "$HOME/.config/tmux/nested-toggle.conf" "$DOTFILES_DIR/tmux/nested-toggle.conf"
fi

if [ "$(uname -s)" = "Darwin" ]; then
  check_link_or_merge aerospace "$HOME/.aerospace.toml" "$DOTFILES_DIR/tools/aerospace.toml" \
    "$DOTFILES_CONFIG_HOME/aerospace.local.toml"
fi

# ------------------------------------
# Check frameworks (installed by install.sh)
# ------------------------------------

echo ""
info "=== Frameworks ==="
echo ""

_zsh_custom="${ZSH_CUSTOM:-$HOME/.oh-my-zsh/custom}"
if module_enabled zsh; then
  check_dir "$HOME/.oh-my-zsh"                             "Oh My Zsh"
  check_dir "$_zsh_custom/plugins/zsh-autosuggestions"     "zsh-autosuggestions"
  check_dir "$_zsh_custom/plugins/zsh-syntax-highlighting" "zsh-syntax-highlighting"
fi
module_enabled tmux && check_dir "$HOME/.tmux/plugins/tpm" "TPM (tmux plugin manager)"
unset _zsh_custom

# ------------------------------------
# Check generated files
# ------------------------------------

echo ""
info "=== Generated files (managed by install.sh) ==="
echo ""

if module_enabled git; then
  if [ -f "$HOME/.gitconfig" ]; then
    if grep -q "# Generated by dotfiles" "$HOME/.gitconfig" 2>/dev/null; then
      success "OK: ~/.gitconfig (generated)"
    else
      warn "MANUAL: ~/.gitconfig was edited outside install.sh"
    fi
  else
    warn "MISSING: ~/.gitconfig (run install.sh)"
  fi
fi

if module_enabled zsh; then
  if [ -d "$HOME/.aliases.d" ]; then
    count=$(find "$HOME/.aliases.d" -name "*.sh" | wc -l | tr -d ' ')
    success "OK: ~/.aliases.d/ ($count generated files)"
  else
    warn "MISSING: ~/.aliases.d/ (run install.sh)"
  fi
fi

for local_dir in $DOTFILES_LOCAL_DIRS; do
  if [ -d "$local_dir" ]; then
    local_count=$(find "$local_dir" -maxdepth 1 -name "*.sh" ! -name install.sh | wc -l | tr -d ' ')
    success "OK: $local_dir ($local_count local files)"
  else
    warn "MISSING: local extensions dir $local_dir"
  fi
done

# ------------------------------------
# Check Claude Code accounts (module: claude)
# ------------------------------------

if module_enabled claude; then
  echo ""
  info "=== Claude Code accounts ==="
  echo ""

  if [ -n "$(claude_account 1 NAME)" ]; then
    if [ -f "$HOME/.aliases.d/claude-accounts.sh" ]; then
      success "OK: ~/.aliases.d/claude-accounts.sh"
    else
      warn "MISSING: ~/.aliases.d/claude-accounts.sh (run install.sh)"
    fi
  else
    warn "No CLAUDE_ACCOUNT_<N>_* defined in config.sh"
  fi

  for i in $(seq 1 99); do
    name="$(claude_account "$i" NAME)"
    [ -z "$name" ] && break
    dir="$(claude_config_dir "$i")"
    if [ "$(claude_account "$i" LINK_HOME)" = true ]; then
      if [ -L "$dir" ] && [ "$(readlink "$dir")" = "$HOME/.claude" ]; then
        success "OK: claude-$name → $dir → ~/.claude"
      else
        warn "NOT LINKED: $dir should link to ~/.claude (run install.sh)"
      fi
    elif [ -d "$dir" ]; then
      success "OK: claude-$name → $dir"
    else
      warn "MISSING: $dir (run install.sh)"
    fi
    if [ "${CLAUDE_STATUSLINE:-true}" != false ] && command -v jq > /dev/null 2>&1; then
      if jq -e --arg cmd "$DOTFILES_DIR/tools/claude-statusline.sh" '.statusLine.command == $cmd' \
         "$dir/settings.json" > /dev/null 2>&1; then
        success "OK: claude-$name status line"
      elif jq -e '.statusLine' "$dir/settings.json" > /dev/null 2>&1; then
        info "claude-$name uses its own status line"
      else
        warn "MISSING: claude-$name status line (run install.sh)"
      fi
    fi
    for pair in $(claude_account "$i" SECRET_ENV); do
      secret_var="${pair#*=}"
      [ -n "${!secret_var:-}" ] || warn "MISSING SECRET: $secret_var (claude-$name) is not set in .secrets"
    done
  done
fi

# ------------------------------------
# Check keyboard layout (module: keyboard-ua-ru, macOS only)
# ------------------------------------

if [ "$(uname -s)" = "Darwin" ] && module_enabled keyboard-ua-ru; then
  echo ""
  info "=== Keyboard layout (macOS) ==="
  echo ""

  # This bundle is copied, not symlinked (see lib/install/keyboard.sh — sandboxed
  # processes can't read a symlink that resolves outside ~/Library/Keyboard
  # Layouts/). Check it's a real copy in sync with the repo, then whether
  # the layout is also active in input sources.
  KBD_BUNDLE_DST="$HOME/Library/Keyboard Layouts/UA-RU-layout.bundle"
  KBD_BUNDLE_SRC="$DOTFILES_DIR/keyboards/UA-RU-layout.bundle"

  if [ -L "$KBD_BUNDLE_DST" ]; then
    warn "SYMLINK: $KBD_BUNDLE_DST (must be a real copy — run install.sh)"
  elif [ ! -e "$KBD_BUNDLE_DST" ]; then
    warn "MISSING: $KBD_BUNDLE_DST (run install.sh)"
  elif diff -rq "$KBD_BUNDLE_SRC" "$KBD_BUNDLE_DST" >/dev/null 2>&1; then
    success "OK: $KBD_BUNDLE_DST (in sync with repo)"
  else
    warn "OUT OF DATE: $KBD_BUNDLE_DST differs from repo (run install.sh)"
  fi
  unset KBD_BUNDLE_DST KBD_BUNDLE_SRC

  if defaults read com.apple.HIToolbox AppleEnabledInputSources 2>/dev/null \
      | grep -q "ua_ru_layout"; then
    success "OK: UA-RU-layout (enabled in input sources)"
  else
    warn "NOT ENABLED: UA-RU-layout is installed but not active"
    warn "  → System Settings → Keyboard → Input Sources → + → 'UA-RU-layout'"
  fi
fi

# ------------------------------------
# Check repo for uncommitted changes
# ------------------------------------

echo ""
info "=== Repository status ==="
echo ""

cd "$DOTFILES_DIR"

if ! git rev-parse --is-inside-work-tree > /dev/null 2>&1; then
  warn "Not a git repository"
  exit 0
fi

# Report only — review and commit changes yourself
if git diff --quiet && git diff --cached --quiet && [ -z "$(git ls-files --others --exclude-standard)" ]; then
  success "No uncommitted changes."
else
  warn "Uncommitted changes (review and commit manually):"
  git status --short
fi
